import{_ as a,o as n,c as e,a2 as p}from"./chunks/framework.D7EuCHIT.js";const d=JSON.parse('{"title":"发布插件与维护仓库","description":"","frontmatter":{},"headers":[],"relativePath":"plugins/publishing.md","filePath":"plugins/publishing.md","lastUpdated":1791877685000}'),l={name:"plugins/publishing.md"};function i(r,s,t,c,o,u){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="发布插件与维护仓库" tabindex="-1">发布插件与维护仓库 <a class="header-anchor" href="#发布插件与维护仓库" aria-label="Permalink to &quot;发布插件与维护仓库&quot;">​</a></h1><p>官方插件使用一个 monorepo，而不是一个插件一个仓库：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LyraPlayer-plugins/</span></span>
<span class="line"><span>  sdk/include/plugin/</span></span>
<span class="line"><span>  plugins/&lt;name&gt;/</span></span>
<span class="line"><span>    manifest.toml</span></span>
<span class="line"><span>    catalog.json</span></span>
<span class="line"><span>    README.md</span></span>
<span class="line"><span>    CHANGELOG.md</span></span>
<span class="line"><span>    icon.png</span></span>
<span class="line"><span>    build.sh</span></span>
<span class="line"><span>    src/</span></span>
<span class="line"><span>    licenses/</span></span>
<span class="line"><span>  catalog/index.json</span></span>
<span class="line"><span>  catalog/index.sig</span></span>
<span class="line"><span>  scripts/catalog.py</span></span>
<span class="line"><span>  scripts/sync.sh</span></span>
<span class="line"><span>  dist/  # ignored：包与对应源码附件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>GitHub 主仓库：<a href="https://github.com/xu-yuanhao/LyraPlayer-plugins" target="_blank" rel="noreferrer">LyraPlayer-plugins</a>。GitLab 镜像：<a href="https://gitlab.com/x13102306563/lyraplayer-plugins" target="_blank" rel="noreferrer">lyraplayer-plugins</a>。它们使用相同提交和发布字节，但 Git 同步不自动同步 Release 附件。</p><h2 id="目录描述" tabindex="-1">目录描述 <a class="header-anchor" href="#目录描述" aria-label="Permalink to &quot;目录描述&quot;">​</a></h2><p>catalog.json 包括 id/title/version/abi/platform/arch/capability/description/tags/author/author_url/homepage/license/icon/readme/changelog/entry/config，以及发布输入 package 和镜像 urls。</p><p>package 只是 dist 下的产物文件名；脚本读取实际 ZIP 计算 bytes 和 SHA-256。不要手填伪造大小或摘要。README/CHANGELOG 的同目录文件内容与 PNG/WebP 图标进入签名索引，原文件同时随包保留。</p><p>签名索引根结构为 <code>schema: 1</code> 与 plugins 数组；schema 是索引格式版本，不是插件 ABI。没有构建产物时目录生成会失败，先构建后更新目录。</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 在官方插件仓库执行，需有本机授权的目录签名私钥。</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">plugins/ffmpeg/build.sh</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/catalog.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>官方 FFmpeg 当前清单版本为 1.0.1，产物文件名以当前 manifest/catalog 和脚本输出为准，不抄 README 里可能过期的旧版本号。</p><h2 id="发布顺序" tabindex="-1">发布顺序 <a class="header-anchor" href="#发布顺序" aria-label="Permalink to &quot;发布顺序&quot;">​</a></h2><p>构建与测试 → 整理许可证及可重建源码 → 在两端上传相同包/对应源码附件 → 核对匿名下载大小与 SHA-256 → 填 urls → 生成并签名索引 → 同步 Git 与索引 → 用设备刷新并验证安装/更新/卸载。</p><p>不要先发布指向不存在文件的新索引。GitLab Generic Package 和 GitHub Release 应是字节一致的镜像；版本比较支持数值段和 SemVer prerelease，不猜未知格式，不降级。</p><p>第三方源可按同一协议提供索引与包，但默认源信任官方公钥。向官方目录贡献插件不代表自动获取官方私钥，需维护者审查并发布。</p><p>下一步：<a href="/LyraPlayer-docs-site/plugins/security">签名与信任</a>、<a href="/LyraPlayer-docs-site/config/repositories">源配置</a>。</p>`,15)])])}const h=a(l,[["render",i]]);export{d as __pageData,h as default};
